import * as React from "react";

import { cn } from "@/lib/utils";

/**
 * Device Shell: a carcaça de alumínio escovado do kit de aparelho (`device-*`).
 *
 * Só a casca: textura escovada, ruído fino, luz na borda de cima, sombra em três camadas.
 * O conteúdo (display, teclas, encoder) entra como filho. O material mora em `device-kit.css`
 * (variáveis `--dk-*`, claro e escuro); aqui não há cor.
 *
 * Tamanhos: `sm` é uma unidade de rack ou um controle de linha (raio 12), `md` o aparelho de
 * bolso do Gravador (raio 36), `lg` um aparelho de mesa.
 */
export type DeviceSize = "sm" | "md" | "lg";

export interface DeviceShellProps extends React.HTMLAttributes<HTMLDivElement> {
  size?: DeviceSize;
}

export const DeviceShell = React.forwardRef<HTMLDivElement, DeviceShellProps>(function DeviceShell(
  { size = "md", className, ...rest },
  ref,
) {
  return <div ref={ref} data-size={size} className={cn("dk-shell", className)} {...rest} />;
});

/** Texto gravado no metal: rótulo de marca, nome de canal, nome do serviço. */
export function DeviceEngraving({ className, ...rest }: React.HTMLAttributes<HTMLSpanElement>) {
  return <span className={cn("dk-engrave", className)} {...rest} />;
}

/** Parafuso de fenda, para as orelhas de uma unidade de rack. Decorativo. */
export function DeviceScrew({ className }: { className?: string }) {
  return <span aria-hidden className={cn("dk-screw", className)} />;
}

import * as React from "react";

import { cn } from "@/lib/utils";

/**
 * Device LCD: o display de vidro do kit de aparelho, com a tinta na luz da marca (`--brand`).
 *
 * `lit` é o backlight: apagado, o vidro fica a 58% e escuro; aceso, a tinta sobe e o fundo
 * esquenta. Use aceso quando o aparelho trabalha (grava, toca, gira) e apagado em repouso.
 *
 * O vidro (reflexo e linhas de varredura) é uma camada por cima, sem pegar clique. O conteúdo
 * vai em `children` e herda a cor da tinta: `DeviceReadout` para o número grande ou o timecode,
 * `DeviceSegments` para um medidor, `DeviceProgress` para uma barra em segmentos.
 */
export interface DeviceLcdProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Backlight aceso. Padrão: aceso. */
  lit?: boolean;
  size?: "sm" | "md";
  /** Classe da tela (o vidro), para altura e respiro. */
  screenClassName?: string;
}

export function DeviceLcd({ lit = true, size = "md", className, screenClassName, children, ...rest }: DeviceLcdProps) {
  return (
    <div data-lit={lit ? "" : undefined} data-size={size} className={cn("dk-lcd", className)} {...rest}>
      <div className={cn("dk-lcd-screen", screenClassName)}>
        <div className="dk-lcd-in">{children}</div>
      </div>
    </div>
  );
}

/** `hh:mm:ss` de um tempo em ms. */
export function timecode(ms: number) {
  const s = Math.max(0, Math.floor(ms / 1000));
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60);
  return [h, m, s % 60].map((n) => String(n).padStart(2, "0")).join(":");
}

export interface DeviceReadoutProps extends React.HTMLAttributes<HTMLDivElement> {
  /** `lg` é o timecode do gravador (38px); `sm` cabe numa unidade de rack. */
  size?: "sm" | "md" | "lg";
  /** Brilho da tinta: o número está vivo (gravando, tocando). */
  glow?: boolean;
}

/** O número do display, em algarismos tabulares para não pular enquanto corre. */
export function DeviceReadout({ size = "lg", glow = false, className, ...rest }: DeviceReadoutProps) {
  return <div data-size={size} data-glow={glow ? "" : undefined} className={cn("dk-readout", className)} {...rest} />;
}

export interface DeviceSegmentsProps {
  /** De 0 a 1. */
  value: number;
  /** Quantos segmentos. Padrão: 10. */
  count?: number;
  /** Com rótulo, vira um `meter` acessível; sem, é só desenho (o valor já está dito em outro lugar). */
  label?: string;
  className?: string;
}

/** Medidor em segmentos de LCD (volume, nível). */
export function DeviceSegments({ value, count = 10, label, className }: DeviceSegmentsProps) {
  const v = Math.min(1, Math.max(0, value));
  const on = Math.round(v * count);
  const a11y = label
    ? { role: "meter" as const, "aria-label": label, "aria-valuemin": 0, "aria-valuemax": 100, "aria-valuenow": Math.round(v * 100) }
    : { "aria-hidden": true };
  return (
    <span className={cn("dk-segments", className)} {...a11y}>
      {Array.from({ length: count }, (_, i) => <i key={i} data-on={i < on ? "" : undefined} />)}
    </span>
  );
}

export interface DeviceProgressProps {
  /** De 0 a 1. Sem valor, a barra fica vazia. */
  value: number;
  segments?: number;
  /** Nome da barra para leitor de tela. */
  label: string;
  /** O que o leitor de tela diz, se a porcentagem não basta ("3 de 12"). */
  valueText?: string;
  className?: string;
}

/** Barra de progresso em segmentos, na tinta do LCD. */
export function DeviceProgress({ value, segments = 24, label, valueText, className }: DeviceProgressProps) {
  const v = Math.min(1, Math.max(0, value));
  const on = Math.round(v * segments);
  return (
    <div role="progressbar" aria-label={label} aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(v * 100)}
      aria-valuetext={valueText} className={cn("dk-progress", className)}>
      {Array.from({ length: segments }, (_, i) => <i key={i} data-on={i < on ? "" : undefined} />)}
    </div>
  );
}

import * as React from "react";

import { cn } from "@/lib/utils";

/**
 * Device LED: a luz de estado do kit de aparelho.
 *
 * - `off` apagado (a lente fica, sem luz);
 * - `on` aceso parado;
 * - `breathe` respira: trabalhando, gravando;
 * - `blink` pisca devagar: em trânsito, pausado, subindo;
 * - `error` aceso em vermelho, qualquer que seja o tom.
 *
 * O tom `red` é a luz de gravação; o `brand` acende no `--brand` da casa. Com movimento
 * reduzido, `breathe` e `blink` ficam acesos parados: o estado continua visível, só não mexe.
 *
 * Com `label`, o LED se anuncia como imagem com nome ("no ar"); sem, é decorativo e o estado
 * precisa estar escrito ao lado.
 */
export type DeviceLedState = "off" | "on" | "breathe" | "blink" | "error";

export interface DeviceLedProps {
  state?: DeviceLedState;
  tone?: "red" | "brand";
  /** `xs` 6px, `sm` 10px, `md` 14px, `lg` 26px (o LED do REC). */
  size?: "xs" | "sm" | "md" | "lg";
  label?: string;
  title?: string;
  className?: string;
}

export function DeviceLed({ state = "off", tone = "brand", size = "sm", label, title, className }: DeviceLedProps) {
  return (
    <span data-state={state} data-tone={tone} data-size={size} title={title}
      className={cn("dk-led", className)}
      {...(label ? { role: "img", "aria-label": label } : { "aria-hidden": true })} />
  );
}

import * as React from "react";

import { cn } from "@/lib/utils";

/**
 * Device Key e Device Switch: as peças que o dedo aperta no kit de aparelho.
 *
 * **DeviceKey** é um botão físico que afunda. Afunda ao apertar (`:active`), por um instante
 * quando um atalho de teclado o aciona (`pressing`, para o atalho e o clique contarem a mesma
 * história) e fica travado afundado com `pressed` (vira `aria-pressed`), como o REC de um
 * gravador enquanto grava. `ring` é o anel torneado; `square`, a tecla pequena.
 *
 * **DeviceSwitch** é a chave deslizante de ligar e desligar (`role="switch"`). `busy` marca o
 * trânsito (subindo, parando): a chave não aceita outro toque até o estado chegar.
 */
export interface DeviceKeyProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  shape?: "ring" | "square";
  size?: "sm" | "md" | "lg";
  /** Travado afundado. Vira `aria-pressed`; sem valor, a tecla não é de alternar. */
  pressed?: boolean;
  /** Afundado por um instante (o atalho de teclado acionou a tecla). */
  pressing?: boolean;
}

export const DeviceKey = React.forwardRef<HTMLButtonElement, DeviceKeyProps>(function DeviceKey(
  { shape = "square", size = "md", pressed, pressing = false, className, type = "button", ...rest },
  ref,
) {
  return (
    <button ref={ref} type={type} data-shape={shape} data-size={size}
      data-pressed={pressing ? "" : undefined} aria-pressed={pressed}
      className={cn("dk-key", className)} {...rest} />
  );
});

/** Marca uma tecla como apertada por um instante: `const [qual, apertar] = usePressFlash()`. */
export function usePressFlash(ms = 140) {
  const [which, setWhich] = React.useState<string | null>(null);
  const t = React.useRef<number>();
  const flash = React.useCallback((k: string) => {
    setWhich(k);
    window.clearTimeout(t.current);
    t.current = window.setTimeout(() => setWhich(null), ms);
  }, [ms]);
  React.useEffect(() => () => window.clearTimeout(t.current), []);
  return [which, flash] as const;
}

export interface DeviceSwitchProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onChange"> {
  checked: boolean;
  onCheckedChange?: (checked: boolean) => void;
  /** Em trânsito: a chave fica onde foi posta e não aceita outro toque. */
  busy?: boolean;
  size?: "sm" | "md";
}

export const DeviceSwitch = React.forwardRef<HTMLButtonElement, DeviceSwitchProps>(function DeviceSwitch(
  { checked, onCheckedChange, busy = false, size = "md", disabled, className, onClick, ...rest },
  ref,
) {
  return (
    <button ref={ref} type="button" role="switch" aria-checked={checked} aria-busy={busy || undefined}
      data-size={size} disabled={disabled || busy}
      onClick={(e) => { onClick?.(e); if (!e.defaultPrevented) onCheckedChange?.(!checked); }}
      className={cn("dk-switch", className)} {...rest}>
      <span className="dk-switch-lit" aria-hidden />
      <span className="dk-switch-thumb" aria-hidden />
    </button>
  );
});

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";

/**
 * Device Encoder: o encoder do kit de aparelho, um controle que anda em detentes.
 *
 * Arrasto vertical (12 px por detente), roda do mouse (um detente a cada 60 de deltaY, com
 * listener não passivo para a página não rolar enquanto gira), setas (cima/direita sobe) e
 * PageUp/PageDown (dez detentes). É um `role="slider"`.
 *
 * Duas formas de usar:
 * - **Valor**: `value`, `min`, `max`, `step` e `onValueChange`. O encoder anda e prende nos
 *   limites; Home/End vão às pontas.
 * - **Detente**: só `onDetent(+1 | -1)`, quando o que o giro faz muda com o estado (o Gravador
 *   navega entre notas parado e é volume tocando). Passe `value/min/max/valueText` para o
 *   leitor de tela saber onde está.
 *
 * `position` controla o desenho (quantos detentes já girou), para quando o giro vem de fora,
 * por exemplo de um atalho de teclado no aparelho inteiro. Sem ela, o encoder conta sozinho.
 *
 * `wheel` é a roda serrilhada de lado; `knob`, o botão giratório com risco de posição.
 */
export interface DeviceEncoderProps {
  variant?: "wheel" | "knob";
  size?: "sm" | "md" | "lg";
  label: string;
  value?: number;
  min?: number;
  max?: number;
  step?: number;
  valueText?: string;
  onValueChange?: (v: number) => void;
  onDetent?: (d: 1 | -1) => void;
  position?: number;
  disabled?: boolean;
  orientation?: "vertical" | "horizontal";
  className?: string;
  style?: React.CSSProperties;
}

const PASSO_ARRASTO = 12; // px por detente
const PASSO_RODA = 60; // deltaY por detente (roda de mouse manda ~100; trackpad soma)
const GRAUS_POR_DETENTE = 15;

export const DeviceEncoder = React.forwardRef<HTMLDivElement, DeviceEncoderProps>(function DeviceEncoder(
  { variant = "wheel", size = "md", label, value, min = 0, max = 100, step = 1, valueText, onValueChange, onDetent,
    position, disabled = false, orientation = "vertical", className, style },
  ref,
) {
  const el = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => el.current!);
  const [proprio, setProprio] = React.useState(0);
  const giro = position ?? proprio;

  // O valor anda aqui também: vários detentes no mesmo quadro (roda, arrasto) chegam antes do render.
  const atual = React.useRef({ value, min, max, step, onValueChange, onDetent, disabled });
  atual.current = { value, min, max, step, onValueChange, onDetent, disabled };
  const detente = React.useCallback((d: 1 | -1) => {
    const a = atual.current;
    if (a.disabled) return;
    setProprio((g) => g + d);
    a.onDetent?.(d);
    if (a.onValueChange && a.value != null) {
      const v = Math.min(a.max, Math.max(a.min, a.value + d * a.step));
      if (v !== a.value) { a.value = v; a.onValueChange(v); }
    }
  }, []);
  const ir = (v: number) => {
    const a = atual.current;
    if (a.disabled || !a.onValueChange || a.value == null || v === a.value) return;
    setProprio((g) => g + Math.sign(v - a.value!));
    a.value = v;
    a.onValueChange(v);
  };

  React.useEffect(() => {
    const no = el.current;
    if (!no) return;
    let soma = 0;
    const roda = (e: WheelEvent) => {
      e.preventDefault();
      soma += e.deltaMode === 1 ? e.deltaY * 40 : e.deltaY;
      while (Math.abs(soma) >= PASSO_RODA) {
        detente(soma < 0 ? 1 : -1);
        soma -= Math.sign(soma) * PASSO_RODA;
      }
    };
    no.addEventListener("wheel", roda, { passive: false });
    return () => no.removeEventListener("wheel", roda);
  }, [detente]);

  const arrasto = React.useRef<{ y: number; resto: number } | null>(null);
  const [arrastando, setArrastando] = React.useState(false);
  const onPointerDown = (e: React.PointerEvent) => {
    if (disabled) return;
    e.currentTarget.setPointerCapture(e.pointerId);
    arrasto.current = { y: e.clientY, resto: 0 };
    setArrastando(true);
  };
  const onPointerMove = (e: React.PointerEvent) => {
    const a = arrasto.current;
    if (!a) return;
    a.resto += a.y - e.clientY; // para cima é positivo
    a.y = e.clientY;
    while (Math.abs(a.resto) >= PASSO_ARRASTO) {
      detente(a.resto > 0 ? 1 : -1);
      a.resto -= Math.sign(a.resto) * PASSO_ARRASTO;
    }
  };
  const soltar = () => { arrasto.current = null; setArrastando(false); };

  const onKeyDown = (e: React.KeyboardEvent) => {
    const k = e.key;
    const f =
      k === "ArrowUp" || k === "ArrowRight" ? () => detente(1)
      : k === "ArrowDown" || k === "ArrowLeft" ? () => detente(-1)
      : k === "PageUp" ? () => { for (let i = 0; i < 10; i++) detente(1); }
      : k === "PageDown" ? () => { for (let i = 0; i < 10; i++) detente(-1); }
      : k === "Home" && onValueChange ? () => ir(min)
      : k === "End" && onValueChange ? () => ir(max)
      : null;
    if (!f) return;
    e.preventDefault(); // um atalho do aparelho inteiro (que olha defaultPrevented) não anda de novo
    f();
  };

  return (
    <div ref={el} role="slider" tabIndex={disabled ? -1 : 0} aria-label={label} aria-orientation={orientation}
      aria-valuemin={min} aria-valuemax={max} aria-valuenow={value} aria-valuetext={valueText}
      aria-disabled={disabled || undefined}
      data-variant={variant} data-size={size} data-dragging={arrastando ? "" : undefined}
      className={cn("dk-encoder", className)} style={style}
      onKeyDown={onKeyDown} onPointerDown={onPointerDown} onPointerMove={onPointerMove} onPointerUp={soltar} onPointerCancel={soltar}>
      {variant === "wheel" ? (
        <span className="dk-knurl" aria-hidden style={{ transform: `translateY(${(((giro * 2) % 8) + 8) % 8}px)` }} />
      ) : (
        <span className="dk-knob-cap" aria-hidden style={{ transform: `rotate(${giro * GRAUS_POR_DETENTE}deg)` }} />
      )}
    </div>
  );
});
